export type ApplauseIconProps = {
	/** Rendered box in pixels. */
	size?: number;
	/** The viewer has applauded — drives the `data-active` styling hook. */
	active?: boolean;
	/** Bump to replay the pop animation; only plays while `active`. */
	playToken?: number;
	className?: string;
};

/**
 * The applause glyph — a raised hand, taken verbatim from the design file.
 *
 * Drawn in `currentColor`, so call sites tint it with `color` instead of
 * stacking `filter` hacks on top of a raster animation.
 */
export function ApplauseIcon({
	size = 18,
	active = false,
	playToken = 0,
	className,
}: ApplauseIconProps) {
	const plays = active && playToken > 0;

	return (
		<span
			key={plays ? `pop-${playToken}` : "idle"}
			className={`${styles.icon}${plays ? ` ${styles.pop}` : ""}${
				className ? ` ${className}` : ""
			}`}
			style={{ width: size, height: size }}
			data-active={active || undefined}
		>
			<svg viewBox="0 0 14 14" aria-hidden="true" focusable="false">
				<title>Applause</title>
				<path d={GEOMETRY} fill="currentColor" />
			</svg>
		</span>
	);
}

export default ApplauseIcon;
